// #2a8411 מסך ניהול משתמשים בחברה (S-02, /users) — общие локаторы и чтение таблицы. Только чтение.
import { Locator, Page, expect } from '@playwright/test';

export const COLUMNS = ['שם', 'אימייל', 'טלפון', 'תפקיד', 'הרשאה', 'סטטוס', 'פעולות'] as const;
export const ROLES = ['מנהל חשבון', 'משתמש רגיל'];
export const STATUSES = ['פעיל', 'הזמנה ממתינה'];
export const LOADING = 'טוען משתמשים…';
export const EMPTY_TITLE = 'אין עדיין משתמשים נוספים בחברה';
export const EMPTY_HINT = 'הזמינו עמיתים כדי שיוכלו לעבוד איתכם על מכרזים.';
export const NO_PERMISSION = 'אין לך הרשאה למסך זה';
export const ACCOUNT_ADMINS_ONLY = 'המסך זמין למנהלי חשבון בלבד.';
/** RPC списка участников (Supabase). */
export const MEMBERS_RPC = '**/rest/v1/rpc/list_company_members*';

export const usersHeading = (page: Page) => page.getByRole('heading', { name: 'משתמשי החברה', level: 1 });
export const usersTable = (page: Page) => page.getByRole('main').getByRole('table');
/** Строки данных (без строки заголовков). */
export const dataRows = (page: Page) => usersTable(page).getByRole('row').filter({ has: page.getByRole('cell') });
export const inviteLinks = (page: Page) => page.getByRole('main').getByRole('link', { name: 'הזמנת משתמש חדש', exact: true });

export type UserRow = { name: string; email: string; role: string; status: string };

/** Роль в ячейке «הרשאה»: у активных — выбранный пункт списка «הרשאה עבור …», у приглашённых — текст. */
async function roleOf(cell: Locator): Promise<string> {
  const combo = cell.getByRole('combobox');
  if (await combo.count()) {
    return combo.evaluate((el) => (el as HTMLSelectElement).selectedOptions[0]?.textContent?.trim() ?? '');
  }
  return (await cell.innerText()).trim();
}

/** Открыть /users и дождаться таблицы. */
export async function openUsers(page: Page) {
  await page.goto('/users');
  await expect(usersHeading(page)).toBeVisible();
  await expect(dataRows(page).first()).toBeVisible();
}

/** Прочитать все строки таблицы. */
export async function readRows(page: Page): Promise<UserRow[]> {
  const rows: UserRow[] = [];
  for (const row of await dataRows(page).all()) {
    const cells = row.getByRole('cell');
    await expect(cells).toHaveCount(COLUMNS.length);
    rows.push({
      name: (await cells.nth(0).innerText()).trim(),
      email: (await cells.nth(1).innerText()).trim(),
      role: await roleOf(cells.nth(4)),
      status: (await cells.nth(5).innerText()).trim(),
    });
  }
  return rows;
}
